import test from 'node:test';
import assert from 'node:assert';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('filters by status and date', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-01', lines: [], payments: [] },
    { number: '002', customerId: 'C2', status: 'paid', dueDate: '2026-10-02', lines: [], payments: [] },
    { number: '003', customerId: 'C3', status: 'partially_paid', dueDate: '2026-10-03', lines: [], payments: [] },
    { number: '004', customerId: 'C4', status: 'draft', dueDate: '2026-10-04', lines: [], payments: [] },
    { number: '005', customerId: 'C5', status: 'issued', dueDate: '2026-10-10', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 2);
  assert.strictEqual(result[0].number, '001');
  assert.strictEqual(result[1].number, '003');
});

test('calculates daysOverdue correctly', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-01', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result[0].daysOverdue, 4);
});

test('calculates due amount correctly', () => {
  const invoices = [
    {
      number: '001',
      customerId: 'C1',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 0 }],
      payments: [{ amount: 30 }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result[0].due, 70);
});

test('returns empty array when no invoices are overdue', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-10', lines: [], payments: [] },
    { number: '002', customerId: 'C2', status: 'paid', dueDate: '2026-10-05', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 0);
});

test('sorts by daysOverdue descending (most overdue first)', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-01', lines: [], payments: [] },
    { number: '002', customerId: 'C2', status: 'issued', dueDate: '2026-10-03', lines: [], payments: [] },
    { number: '003', customerId: 'C3', status: 'issued', dueDate: '2026-10-02', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result[0].number, '001');
  assert.strictEqual(result[0].daysOverdue, 4);
  assert.strictEqual(result[1].number, '003');
  assert.strictEqual(result[1].daysOverdue, 3);
  assert.strictEqual(result[2].number, '002');
  assert.strictEqual(result[2].daysOverdue, 2);
});

test('includes both issued and partially_paid invoices', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-01', lines: [], payments: [] },
    { number: '002', customerId: 'C2', status: 'partially_paid', dueDate: '2026-10-02', lines: [], payments: [{ amount: 50 }] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 2);
});

test('excludes paid and draft invoices', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'paid', dueDate: '2026-10-01', lines: [], payments: [] },
    { number: '002', customerId: 'C2', status: 'draft', dueDate: '2026-10-02', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 0);
});

test('includes invoices exactly at asOf date when dueDate is before', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-04', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 1);
});

test('excludes invoices when dueDate equals asOf', () => {
  const invoices = [
    { number: '001', customerId: 'C1', status: 'issued', dueDate: '2026-10-05', lines: [], payments: [] },
  ];

  const result = overdueInvoices(invoices, '2026-10-05');

  assert.strictEqual(result.length, 0);
});

test('vatSummary groups VAT by rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, vatRate: 20 },
        { qty: 1, unitPrice: 100, vatRate: 10 },
      ],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result.length, 2);
  assert.strictEqual(result[0].rate, 20);
  assert.strictEqual(result[1].rate, 10);
});

test('vatSummary calculates base (line total minus discount)', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 10, unitPrice: 100, discountPercent: 20, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].base, 800);
});

test('vatSummary calculates VAT correctly', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].base, 100);
  assert.strictEqual(result[0].vat, 20);
});

test('vatSummary sums multiple lines with same VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, vatRate: 20 },
        { qty: 1, unitPrice: 200, vatRate: 20 },
      ],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].rate, 20);
  assert.strictEqual(result[0].base, 300);
  assert.strictEqual(result[0].vat, 60);
});

test('vatSummary sums across multiple invoices', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
    {
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].base, 200);
  assert.strictEqual(result[0].vat, 40);
});

test('vatSummary sorts by rate descending', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, vatRate: 10 },
        { qty: 1, unitPrice: 100, vatRate: 20 },
        { qty: 1, unitPrice: 100, vatRate: 5 },
      ],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result.length, 3);
  assert.strictEqual(result[0].rate, 20);
  assert.strictEqual(result[1].rate, 10);
  assert.strictEqual(result[2].rate, 5);
});

test('vatSummary filters by status (issued, partially_paid, paid only)', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
    {
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
    {
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].base, 200);
  assert.strictEqual(result[0].vat, 40);
});

test('vatSummary includes paid invoices', () => {
  const invoices = [
    {
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result.length, 1);
  assert.strictEqual(result[0].base, 100);
});

test('vatSummary returns empty array when no invoices match', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result.length, 0);
});

test('vatSummary handles zero VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 0 }],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result[0].rate, 0);
  assert.strictEqual(result[0].base, 100);
  assert.strictEqual(result[0].vat, 0);
});

test('vatSummary with multiple rates and discounts', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, discountPercent: 10, vatRate: 20 },
        { qty: 2, unitPrice: 50, discountPercent: 0, vatRate: 10 },
      ],
    },
  ];

  const result = vatSummary(invoices);

  assert.strictEqual(result.length, 2);
  assert.strictEqual(result[0].rate, 20);
  assert.strictEqual(result[0].base, 90);
  assert.strictEqual(result[0].vat, 18);
  assert.strictEqual(result[1].rate, 10);
  assert.strictEqual(result[1].base, 100);
  assert.strictEqual(result[1].vat, 10);
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoice = {
    dueDate: '2026-10-10',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-10-10');

  assert.strictEqual(fee, 0);
});

test('lateFee returns 0 when invoice is due in future', () => {
  const invoice = {
    dueDate: '2026-10-15',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-10-10');

  assert.strictEqual(fee, 0);
});

test('lateFee calculates 0.04% per day overdue', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-10-02');

  // 10000 cents * 1 day * 0.0004 = 4 cents
  assert.strictEqual(fee, 4);
});

test('lateFee compounds with multiple days overdue', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-10-11');

  // 10000 cents * 10 days * 0.0004 = 40 cents
  assert.strictEqual(fee, 40);
});

test('lateFee accounts for amount still due', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 5000, vatRate: 0 }],
    payments: [{ amount: 2000 }],
  };

  const fee = lateFee(invoice, '2026-10-06');

  // (5000 - 2000) * 5 days * 0.0004 = 3000 * 5 * 0.0004 = 6 cents
  assert.strictEqual(fee, 6);
});

test('lateFee returns 0 when fully paid', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    payments: [{ amount: 10000 }],
  };

  const fee = lateFee(invoice, '2026-10-11');

  assert.strictEqual(fee, 0);
});

test('lateFee with VAT-inclusive line', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
  };

  const fee = lateFee(invoice, '2026-10-02');

  // line total: 100, vat: 20, total: 120 cents
  // fee: 120 * 1 * 0.0004 = 0.048 -> rounds to 0
  assert.strictEqual(fee, 0);
});

test('lateFee with larger VAT-inclusive amount', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 50000, vatRate: 20 }],
  };

  const fee = lateFee(invoice, '2026-10-02');

  // line total: 50000, vat: 10000, total: 60000 cents
  // fee: 60000 * 1 * 0.0004 = 24 cents
  assert.strictEqual(fee, 24);
});

test('lateFee handles partial payments across multiple lines', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [
      { qty: 1, unitPrice: 5000, vatRate: 0 },
      { qty: 1, unitPrice: 5000, vatRate: 0 },
    ],
    payments: [{ amount: 5000 }],
  };

  const fee = lateFee(invoice, '2026-10-06');

  // total: 10000, paid: 5000, due: 5000
  // fee: 5000 * 5 * 0.0004 = 10 cents
  assert.strictEqual(fee, 10);
});

test('lateFee with many days overdue', () => {
  const invoice = {
    dueDate: '2026-01-01',
    lines: [{ qty: 1, unitPrice: 100000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-01-31');

  // 100000 * 30 * 0.0004 = 1200 cents
  assert.strictEqual(fee, 1200);
});

